/**
 * Unit tests for BasicSerializerFactory#findSuppressableContentValue.
 * Since the method is protected, we use a subclass to expose it for testing.
 */
public class BasicSerializerFactory_findSuppressableContentValue_TriageGen2Test {

    private TestableBasicSerializerFactory factory;
    private SerializationConfig mockConfig;
    private JavaType mockContentType;
    private BeanDescription mockBeanDesc;

    /**
     * Subclass to allow testing of the protected method.
     */
    private static class TestableBasicSerializerFactory extends BasicSerializerFactory {
        protected TestableBasicSerializerFactory() {
            super(null);
        }

        @Override
        protected Iterable<com.fasterxml.jackson.databind.JsonSerializer<?>> customSerializers() {
            return null;
        }

        @Override
        public findSuppressableContentValue(SerializationConfig config, JavaType contentType, BeanDescription beanDesc)
                throws JsonMappingException {
            return super.findSuppressableContentValue(config, contentType, beanDesc);
        }
    }

    @Before
    public void setUp() {
        factory = new TestableBasicSerializerFactory();
        mockConfig = Mockito.mock(SerializationConfig.class);
        mockContentType = Mockito.mock(JavaType.class);
        mockBeanDesc = Mockito.mock(BeanDescription.class);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNullWhenInclusionIsNull() throws JsonMappingException {
        // Arrange
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(null);

        // Act
        Object result = factory.findSuppressableContentValue(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertNull("Should return null when inclusion is null", result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsNonEmptyWhenInclusionIsNonDefault() throws JsonMappingException {
        // Arrange
        // The code explicitly converts NON_DEFAULT to NON_EMPTY
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(JsonInclude.Include.NON_DEFAULT);

        // Act
        Object result = factory.findSuppressableContentValue(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("NON_DEFAULT should be converted to NON_EMPTY", JsonInclude.Include.NON_EMPTY, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsOriginalInclusionForOtherModes() throws JsonMappingException {
        // Arrange
        JsonInclude.Include targetInclude = JsonInclude.Include.NON_NULL;
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(targetInclude);

        // Act
        Object result = factory.findSuppressableContentValue(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Should return the original inclusion mode if not NON_DEFAULT", targetInclude, result);
    }

    @Test
    public void testFindSuppressableContentValue_ReturnsAlwaysInclude() throws JsonMappingException {
        // Arrange
        JsonInclude.Include targetInclude = JsonInclude.Include.ALWAYS;
        when(mockBeanDesc.findSerializationInclusionForContent(null)).thenReturn(targetInclude);

        // Act
        Object result = factory.findSuppressableContentValue(mockConfig, mockContentType, mockBeanDesc);

        // Assert
        assertEquals("Should return ALWAYS when requested", targetInclude, result);
    }
}
